const timestamp: string = stepStdout(readBatch, 'timestamp') || ''
const today = timestamp ? timestamp.slice(0, 10) : '(date unavailable)'
const specPath = `${epicDir}/SPEC.md`
const questionsPath = `${epicDir}/QUESTIONS.md`

